/**
 * KaunTech AR gallery — the curated catalogue of ready-made 3D models the editor
 * offers under "Choose from KaunTech gallery". Each entry points at a .glb in the
 * public `ar-gallery` Supabase bucket. Picking one inserts a real `model` element
 * (genuine 3D in the WebAR viewer), unlike the flat social/text/image billboards.
 *
 * The list itself is generated by scripts/ar-gallery/ingest.mjs from a folder of
 * .glb files — DO NOT hand-edit gallery.generated.json; re-run the ingest script.
 */
import generated from "./gallery.generated.json";

export type GalleryCategory = "social" | "arrows" | "avatars" | "objects";

export interface GalleryAsset {
  /** Stable slug, unique across the catalogue. */
  id: string;
  /** Display name shown under the preview. */
  name: string;
  category: GalleryCategory;
  /** Public .glb URL in the ar-gallery bucket. */
  glbUrl: string;
  /** Loop the glb's baked animation in the editor preview and the viewer. */
  animated?: boolean;
  /** Social platform key — pre-fills the tap-link prefix for icon "coins". */
  platform?: string;
  /** Scale to drop the element in at (card-width units). Defaults to 0.45. */
  defaultScale?: number;
}

export const GALLERY_CATEGORIES: { key: GalleryCategory; label: string }[] = [
  { key: "social", label: "Social" },
  { key: "arrows", label: "Arrows" },
  { key: "avatars", label: "Avatars" },
  { key: "objects", label: "Objects" },
];

export const AR_GALLERY: GalleryAsset[] = generated as GalleryAsset[];

export function galleryByCategory(category: GalleryCategory): GalleryAsset[] {
  return AR_GALLERY.filter((a) => a.category === category);
}

/** Categories that actually have at least one model — for hiding empty tabs. */
export function nonEmptyCategories(): { key: GalleryCategory; label: string }[] {
  return GALLERY_CATEGORIES.filter((c) => AR_GALLERY.some((a) => a.category === c.key));
}
